import test from'node:test';import assert from'node:assert/strict';import{make,validate,apply}from'./state.js';import{history,transition,undo,portable,parse}from'../creative-kit/state.js';const config={make,validate,apply};
test('moving ideas changes the map without losing assumptions; axis rename preserves coordinates',()=>{const w=make(),idea=structuredClone(w.ideas[0]);apply(w,{type:'move',id:'i1',cell:'n2|m2'});assert.equal(w.ideas[0].assumption,idea.assumption);apply(w,{type:'edit',collection:'methods',item:'m2',field:'label',value:'Learning by rehearsal'});assert.equal(w.ideas[0].method,'m2');validate(w);});
test('examining a gap does not manufacture an idea; creation and Undo retain the gap reasoning',()=>{const w=make();apply(w,{type:'edit',collection:'gap',field:'reason',value:'We assumed information must arrive as a dashboard.'});const before=w.ideas.length;let h=history({version:1,activeId:w.id,workspaces:[w]});h=transition(h,{type:'add-idea',id:'i5',cell:w.selected},config);assert.equal(h.present.workspaces[0].ideas.length,before+1);assert.deepEqual(undo(h).present.workspaces[0],w);assert.deepEqual(parse(portable(w,'territory',validate),'territory',validate),w);});
